def build_agent(sandbox):
    # Main beam (main body) at x=4.5, y=2.0, height 3.0, width 0.4, density 5.0
    main_beam = sandbox.add_beam(x=4.5, y=2.0, width=0.4, height=3.0, density=5.0)

    # Add 6 more beams connected via pivot joints
    prev_b = main_beam
    joints = []
    for i in range(6):
        y = 2.0 + (i+1)*3.0
        b = sandbox.add_beam(x=4.5, y=y, width=0.4, height=3.0, density=5.0)
        pivot_point = (4.5, y - 1.5)
        joint = sandbox.add_joint(prev_b, b, pivot_point, type='pivot')
        joints.append(joint)
        prev_b = b

    # Add pads at the bottom of each beam
    pads = []
    for beam in [main_beam, prev_b]:
        pad = sandbox.add_pad(x=4.5, y=beam.position.y - 1.5, radius=0.12, density=1.0)
        pads.append(pad)
        joint = sandbox.add_joint(beam, pad, (4.5, beam.position.y - 1.5), type='pivot')

    return {
        'control': {
            'joints': joints,
            'p_torso': pads,
            'cycle': 10,
            'overlap': 5,
            'speed': 5.0,
            'torque': 100.0
        }
    }

def agent_action(sandbox, agent_body, step_count):
    _apply_climb_action(sandbox, agent_body, step_count)
